/* ===== Numeria Quest — NPC dari gambar referensi (96x128) =====
   Dimuat SETELAH npc_pixel.js dan SEBELUM npc_apply.js.
   Sprite diambil LANGSUNG dari dua gambar referensi (Fantasy Kingdom + Indonesian Village), bukan hasil render ulang:
     - atlas besar  96x128 per sel -> potret dialog
     - atlas kecil  24x32  per sel -> NPC di peta dunia (sudah diperkecil rapi dari 96x128, tepi bersih)
   API: NPCIMG.ready, NPCIMG.has(kunci), NPCIMG.pick(kunci, seed) -> indeks sel,
        NPCIMG.big(ctx, idx, x, y, w, h), NPCIMG.small(ctx, idx, x, y) */
/* Tinggi sprite NPC & hero di dunia (piksel peta, untuk 128 baris sprite). Ubah angka ini untuk membesar/mengecilkan keduanya sekaligus. */
var NPC_WORLD_H = 32;
const NPCIMG = (() => {
  const IDS = ["f0", "f1", "f2", "f3", "f4", "f5", "f6", "f7", "f8", "f9", "f10", "f11", "f12", "f13", "f14", "f15", "f16", "f17", "f18", "f19", "f20", "f21", "f22", "f23", "f24", "f25", "f26", "f27", "f28", "f29a", "f29b", "f30", "f31", "f32", "f33", "f34", "f35", "f36", "f37", "f38", "f39", "f40", "f41", "f42", "f43", "f44", "f45", "f46", "f47", "f48", "f49", "f50", "f51a", "f51b", "f52", "f53", "f54", "f55", "f56", "f57", "f58", "f59", "f60", "f61", "f62", "f63", "f64", "f65", "f66", "f67", "f68", "f69", "f70", "f71", "f72", "f73", "f74", "v0", "v1", "v2", "v3", "v4", "v5", "v6", "v7", "v8", "v9", "v10", "v11", "v12", "v13", "v14", "v15", "v16", "v17", "v18", "v19", "v20", "v21", "v22", "v23", "v24", "v25", "v26", "v27", "v28", "v29", "v30", "v31", "v32", "v33", "v34", "v35", "v36", "v37", "v38", "v39", "v40", "v41", "v42a", "v42b", "v43", "v44", "v45", "v46", "v47a", "v47b", "v48", "v49", "v50", "v51", "v52", "v53", "v54", "v55", "v56", "v57", "v58", "v59", "v60", "v61", "v62", "v63", "v64", "v65", "v66", "v67", "v68", "v69", "v70", "v71", "v72", "v73", "v74", "v75", "v76", "v77", "v78", "v79", "v80", "v81"],
    MAP = {"prajurit": ["f0", "f1", "f2", "f3", "f4"], "penjaga": ["f0", "f1", "f2", "f3", "f4"], "wali": ["f5", "f6", "f7", "f8", "f9"], "balai": ["f10", "f11", "f12", "f13", "f14"], "tabib": ["f15", "f16", "f17", "f18", "f19", "f20"], "pendeta": ["f17", "f15", "f16", "f19"], "ksatria": ["f21", "f22", "f23", "f24", "f25"], "kapten": ["f22", "f21", "f24", "f23"], "pveteran": ["f23", "f21", "f25"], "gerbang": ["f26", "f27", "f28", "f29a", "f29b"], "pejabat": ["f30", "f31", "f32", "f33", "f34", "f35"], "bangsawan": ["f36", "f37", "f38", "f39", "f40", "f41"], "tamu": ["f42", "f43", "f44", "f45", "f46", "f47"], "pelayan": ["f48", "f49", "f50", "f51a", "f51b", "f52"], "rajalaut": ["f53", "f54", "f55", "f56", "f57"], "ratulaut": ["f58", "f59", "f60", "f61", "f62"], "pangeran": ["f63", "f64", "f65", "f66", "f67", "f68"], "putri": ["f69", "f70", "f71", "f72", "f73", "f74"], "pria": ["v0", "v2", "v4", "v3"], "tukangkebun": ["v0", "v2"], "pandai": ["v3"], "warga": ["v5", "v72", "v73", "v74", "v75", "v76", "v77", "v78", "v79", "v80", "v81"], "pria2": ["v5", "v72", "v73", "v74", "v76", "v79", "v80"], "tukangsapu": ["v75", "v77", "v80"], "musisi": ["v78", "v81", "v77"], "pembaca": ["v74", "v79", "v73"], "wanita": ["v1", "v25", "v26", "v27", "v28", "v29", "v30", "v31", "v32", "v33"], "ibu": ["v25", "v26", "v27", "v28", "v29", "v30", "v31", "v32", "v33"], "pos": ["v6", "v7", "v8", "v9", "v10", "v11"], "nelayan": ["v19", "v20", "v21", "v22", "v23", "v24"], "dagang": ["v4", "f45", "f46"], "kakek": ["v12", "v13", "v14", "v15"], "kakek2": ["v12", "v13", "v14", "v15"], "nenek": ["v16", "v17", "v18"], "bocah": ["v37", "v38", "v39", "v40", "v41", "v34", "v35", "v36"], "anak": ["v37", "v38", "v39", "v40", "v41", "v34", "v35", "v36"], "pdekar": ["v47a", "v47b", "v48", "v42a", "v42b", "v49"], "pmage": ["v44", "v61", "v62", "v45", "v46", "v63"], "pmanah": ["v53", "v54", "v43", "v51", "v52"], "ranger": ["v53", "v54", "v43", "v51", "v52"], "pencuri": ["v51", "v48", "v52"], "wizard": ["v64", "v65", "v66", "v67", "v68", "v69", "v70", "v71"], "euclid": ["f5"], "lyra": ["f22"], "fib": ["f8"], "toko": ["v4"], "tetua": ["f9"], "seniman": ["v81"], "pedagangkuno": ["f45"], "penginap": ["v29"]},
    COLS = 16;
  const B = new Image(), S = new Image();
  let n = 0;
  const api = { ready: false, IDS, MAP };
  const done = () => { if (++n === 2) api.ready = true; };
  B.onload = S.onload = done;
  B.src = "data:image/png;base64,";
  S.src = "data:image/png;base64,";
  api.has = (k) => !!MAP[k];
  api.pick = (k, seed) => {
    const l = MAP[k];
    return l ? IDS.indexOf(l[(seed >>> 0) % l.length]) : -1;
  };
  api.big = (c, i, x, y, w, h) => c.drawImage(B, (i % COLS) * 96, ((i / COLS) | 0) * 128, 96, 128, x, y, w, h);
  api.small = (c, i, x, y) => c.drawImage(S, (i % COLS) * 24, ((i / COLS) | 0) * 32, 24, 32, x, y, 24, 32);
  return api;
})();
